/**
 * RobotkezV2Agent - Hybrid Browser Automation (Playwright + Browser-Use)
 *
 * Bridge between TypeScript (MCP agent) and Python hybrid engine
 * (myai/agents/robotkez_v2_hybrid.py)
 *
 * Modes:
 * - auto: Complexity analyzer decides (keyword-based)
 * - playwright: Fast, fixed selectors (screenshot, PDF, navigate)
 * - browser-use: AI-powered, flexible (Gemini 2.0 Flash)
 *
 * @author Claude Code + Pohánka Péter
 * @track robotkezv2-hybrid-20260217
 */

import { BaseAgent, AgentContext, AgentResult } from './BaseAgent.js';
import { logInfo, logError, setAgentStatus } from '../utils/logger.js';
import { backgroundTaskManager } from '../utils/backgroundTaskManager.js';
import { BrowserCommand } from '../utils/persistentBrowser.js';
import { getRobotkezBrowserEngine } from '../utils/browserEngine.js';
import { generateExecutionPlan, ExecutionPlan } from '../utils/llmPlanner.js';
import { socketService } from '../server/SocketService.js';

// No longer using execAsync here

export interface RobotkezV2Options {
  mode?: 'auto' | 'playwright' | 'browser-use';
  headless?: boolean;
  screenshot_path?: string;
  pdf_path?: string;
  selector?: string;
  timeout?: number;
  url?: string;
}

export class RobotkezV2Agent extends BaseAgent {
  name = 'RobotkezV2';
  role = 'Magyar Agentic Browser (Comet Stílus)';
  description = 'Folyékonyan kommunikáló, proaktív böngésző ügynök vizuális visszajelzéssel.';
  capabilities = [
    'browser_automation',
    'screenshot',
    'pdf_generation',
    'web_scraping',
    'ai_browsing',
    'multi_step_workflow',
    'magyar_nyelv',
    'agentic_browsing'
  ];

  private chatEndpoint = process.env.BROWSER_CHAT_ENDPOINT || 'http://localhost:8000/browser/chat';
  private screenshotEndpoint = process.env.BROWSER_SCREENSHOT_ENDPOINT || 'http://localhost:8000/browser/screenshot';

  async chat(message: string, sessionId?: string): Promise<string> {
    logInfo(this.name, `Chat request: ${message}`);

    try {
      const importAxios = await import('axios');
      const axios = importAxios.default;
      const response = await axios.post(this.chatEndpoint, {
        message,
        sessionId: sessionId || this.generateSessionId()
      });

      const data = response.data;

      if (data.screenshot) {
        await this.saveScreenshot(sessionId, data.screenshot);
      }

      return data.response;
    } catch (error) {
      logError(this.name, `Chat error: ${error}`);
      return 'Hiba történt a böngésző interakcióban. Kérlek próbáld újra.';
    }
  }

  async takeScreenshot(sessionId?: string): Promise<string> {
    try {
      const importAxios = await import('axios');
      const axios = importAxios.default;
      const response = await axios.get(this.screenshotEndpoint, {
        responseType: 'arraybuffer'
      });

      const screenshot = Buffer.from(response.data, 'binary').toString('base64');
      await this.saveScreenshot(sessionId, screenshot);

      return screenshot;
    } catch (error) {
      logError(this.name, `Screenshot error: ${error}`);
      throw error;
    }
  }

  private async saveScreenshot(sessionId: string | undefined, screenshot: string): Promise<void> {
    const sessionDir = sessionId
      ? `data/screenshots/${sessionId}`
      : `data/screenshots/${Date.now()}`;

    try {
      const fs = await import('fs/promises');
      // Mappa létrehozása (ha nem létezik)
      await fs.mkdir(sessionDir, { recursive: true });

      // Screenshot mentése
      const filename = `screenshot_${Date.now()}.png`;
      await fs.writeFile(
        `${sessionDir}/${filename}`,
        Buffer.from(screenshot, 'base64')
      );

      logInfo(this.name, `Screenshot mentve: ${sessionDir}/${filename}`);
    } catch (err) {
      logError(this.name, `Failed to save screenshot: ${err}`);
    }
  }

  private generateSessionId(): string {
    return `session_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;
  }

  /**
   * Internal execution logic - implements BaseAgent.executeTask
   */
  async executeTask(context: AgentContext): Promise<AgentResult> {
    const task = (context.task || '').trim();
    setAgentStatus(this.name, 'working', task.slice(0, 50));

    try {
      const browserEngine = getRobotkezBrowserEngine();

      // 1. Simple Intent Parsing (Phase 2 compatibility for tests)
      let plan: ExecutionPlan | null = null;
      
      const taskLower = task.toLowerCase();
      if (taskLower.includes('navigálj') || taskLower.includes('frissíts')) {
        let url = task.match(/https?:\/\/[^\s]+/)?.[0];
        if (!url && !taskLower.includes('frissíts')) {
           const domainMatch = task.match(/([a-z0-9]+\.)+[a-z]{2,}/i);
           if (domainMatch) url = `https://${domainMatch[0]}`;
        }
        
        if (url || taskLower.includes('frissíts')) {
          plan = {
            plan: [
              { 
                action: url ? 'navigate' : 'screenshot', 
                url: url, 
                description: url ? `Navigálás a(z) ${url} weboldalra` : 'Oldal frissítése és szinkronizálása' 
              }
            ],
            estimatedDuration: 5000,
            backgroundEligible: false
          };
        } else {
          // Fallback to search if "navigálj" but no URL
          const query = task.replace(/navigálj/i, '').trim();
          plan = {
            plan: [{ action: 'navigate', url: `https://www.google.com/search?q=${encodeURIComponent(query)}`, description: `Keresés indítása: ${query}` }],
            estimatedDuration: 5000,
            backgroundEligible: false
          };
        }
      } else if (taskLower.includes('keress rá')) {
        const query = task.replace(/keress rá a? /i, '').trim();
        plan = {
          plan: [{ action: 'navigate', url: `https://www.google.com/search?q=${encodeURIComponent(query)}`, description: `Google keresés: ${query}` }],
          estimatedDuration: 5000,
          backgroundEligible: false
        };
      } else if (taskLower.includes('kattints')) {
        const selector = task.match(/['"]([^'"]+)['"]/)?.[1] || (taskLower === 'kattints' ? '.primary-button' : null);
        if (selector) {
          plan = {
            plan: [{ action: 'click', selector, description: `Kattintás a(z) '${selector}' elemre` }],
            estimatedDuration: 3000,
            backgroundEligible: false
          };
        }
      } else if (taskLower.includes('írj be') || taskLower.includes('gépelj')) {
        const text = task.match(/['"]([^'"]+)['"]/)?.[1] || 'Hello World';
        const selector = task.match(/a '([^']+)' mezőbe/)?.[1] || 'input';
        plan = {
          plan: [{ action: 'type', selector, text, description: `Szöveg beírása a(z) '${selector}' mezőbe: "${text}"` }],
          estimatedDuration: 4000,
          backgroundEligible: false
        };
      } else if (taskLower.includes('képernyőkép')) {
        plan = {
          plan: [{ action: 'screenshot', description: 'Pillanatkép készítése a jelenlegi oldalról' }],
          estimatedDuration: 3000,
          backgroundEligible: false
        };
      }

      // 2. LLM Plan Generation (if not already parsed or for Phase 3+)
      if (!plan) {
        try {
          // Get current browser state if possible
          let browserState;
          try {
             const stateResponse = await browserEngine.sendCommand({ action: 'state' });
             if (stateResponse.status === 'success') {
                browserState = {
                  url: stateResponse.url || '',
                  title: stateResponse.title
                };
             }
          } catch {
             // Ignored
          }

          plan = await generateExecutionPlan(task, {
            history: context.swarm?.history,
            browserState: browserState
          });
        } catch {
          // Final fallback
          plan = {
            plan: [{ action: 'navigate', url: `https://www.google.com/search?q=${encodeURIComponent(task)}`, description: 'Általános keresés indítása' }],
            estimatedDuration: 5000,
            backgroundEligible: false
          };
        }
      }

      // EMIT PLAN to Dashboard (Comet-style)
      socketService.emit('robotkez:plan', { taskId: `rk-${Date.now()}`, plan });

      // 3. Background Delegation (Phase 4.4)
      if (context.backgroundEligible || plan.estimatedDuration > 30000 || plan.backgroundEligible) {
        const taskId = await backgroundTaskManager.startTask(task, plan);
        return {
          success: true,
          message: `Rendben, elindítottam a feladatot a háttérben. A folyamatot a "Background Tasks" panelen követheted nyomon. (Task ID: ${taskId})`,
          data: { taskId, background: true }
        };
      }

      // 4. Sequential execution via selected browser engine
      logInfo(this.name, `Executing plan: ${plan.plan.length} steps`);
      const completedSteps: unknown[] = [];

      for (let i = 0; i < plan.plan.length; i++) {
        const step = plan.plan[i];
        logInfo(this.name, `Step: ${step.description} (${step.action})`);
        
        // EMIT STEP START
        socketService.emit('robotkez:step', { index: i, status: 'working', description: step.description });

        try {
          // DYNAMIC VISION: If selector is missing but description exists, use query
          if (['click', 'type', 'wait', 'extract'].includes(step.action) && !step.selector && step.description) {
             logInfo(this.name, `Dynamic vision query for: ${step.description}`);
             const queryResp = await browserEngine.sendCommand({
                action: 'query',
                description: step.description
             });
             if (queryResp.status === 'success') {
                const queryData = queryResp.data as Record<string, unknown>;
                if (queryData.selector) {
                   step.selector = String(queryData.selector);
                   logInfo(this.name, `Resolved selector: ${step.selector}`);
                } else {
                   throw new Error(`Nem találtam meg a következő elemet: "${step.description}"`);
                }
             } else {
                throw new Error(`Nem találtam meg a következő elemet: "${step.description}"`);
             }
          }

          // Strip description and other non-command properties for browser compatibility
          // eslint-disable-next-line @typescript-eslint/no-unused-vars
          const { description: _desc, ...command } = step as unknown as Record<string, unknown>;
          // Ensure type safety
          const browserCommand = command as unknown as BrowserCommand;
          const response = await browserEngine.sendCommand(browserCommand);
          
          completedSteps.push({
            ...step,
            status: 'completed',
            result: response
          });

          // EMIT STEP SUCCESS
          socketService.emit('robotkez:step', { 
            index: i, 
            status: 'completed', 
            screenshot: response.screenshot // If returned by action
          });

        } catch (stepError: unknown) {
          const msg = stepError instanceof Error ? stepError.message : String(stepError);
          const action = step.action;
          logError(this.name, `Step failed: ${step.description} - ${msg}`);
          
          completedSteps.push({
            ...step,
            status: 'error',
            error: msg
          });

          // EMIT STEP ERROR
          socketService.emit('robotkez:step', { index: i, status: 'error', error: msg });
          
          // Stop on critical error
          if (['navigate', 'click', 'type'].includes(action)) {
             return {
               success: false,
               message: `Sajnos nem sikerült végrehajtani a következő lépést: "${step.description}". Hibaüzenet: ${msg}`
             };
          }
        }
      }

      // 5. Auto-Screenshot (Phase 2 expectation)
      let screenshotResult;
      try {
        screenshotResult = await browserEngine.sendCommand({ action: 'screenshot' });
      } catch {
        // Ignored
      }

      const isScreenshotTask = taskLower.includes('képernyőkép');
      const baseMessage = isScreenshotTask
        ? 'Elkészítettem a kért képernyőképet.'
        : `Sikeresen végrehajtottam a feladatot: "${task}".`;

      return {
        success: true,
        message: baseMessage,
        data: {
           completedSteps,
           screenshot: screenshotResult?.screenshot,
           success: true // Legacy support
        }
      };

    } catch (e: unknown) {
      const msg = e instanceof Error ? e.message : String(e);
      logError(this.name, `Execution failed: ${msg}`);
      return {
        success: false,
        message: `Hiba történt a végrehajtás során: ${msg}`
      };
    } finally {
      setAgentStatus(this.name, 'idle');
    }
  }

  // Phase 4.4 Background Task Methods
  async executeInBackground(task: string): Promise<{ taskId: string; plan?: ExecutionPlan }> {
    const plan = await generateExecutionPlan(task);
    const taskId = await backgroundTaskManager.startTask(task, plan);
    return { taskId, plan };
  }

  getBackgroundTaskStatus(taskId: string) {
    return backgroundTaskManager.getTaskStatus(taskId);
  }

  cancelBackgroundTask(taskId: string) {
    return backgroundTaskManager.cancelTask(taskId);
  }

  listBackgroundTasks() {
    return backgroundTaskManager.getAllTasks();
  }

  /**
   * Execute with explicit mode (convenience method)
   *
   * @param task - Instruction
   * @param mode - Execution mode
   * @param options - Additional options
   */
  async executeWithMode(
    task: string,
    mode: 'auto' | 'playwright' | 'browser-use',
    options?: Partial<RobotkezV2Options>
  ): Promise<unknown> {
    return this.execute(task, { ...options, mode });
  }

  /**
   * Screenshot convenience method
   *
   * @param url - Target URL
   * @param screenshotPath - Output path (default: screenshot.png)
   */
  async screenshot(url: string, screenshotPath?: string): Promise<unknown> {
    return this.execute(`screenshot ${url}`, {
      mode: 'playwright', // Force Playwright (fast)
      url,
      screenshot_path: screenshotPath || 'screenshot.png'
    });
  }

  /**
   * PDF generation convenience method
   *
   * @param url - Target URL
   * @param pdfPath - Output path (default: page.pdf)
   */
  async generatePdf(url: string, pdfPath?: string): Promise<unknown> {
    return this.execute(`pdf ${url}`, {
      mode: 'playwright', // Force Playwright (fast)
      url,
      pdf_path: pdfPath || 'page.pdf'
    });
  }

  /**
   * AI-powered complex task (force Browser-Use)
   *
   * @param instruction - Natural language instruction
   */
  async aiTask(instruction: string): Promise<unknown> {
    return this.execute(instruction, {
      mode: 'browser-use' // Force AI mode
    });
  }
}

export default RobotkezV2Agent;

import React, { useState, useEffect } from 'react';
import { Play, Square, Camera, RefreshCw, Terminal, Activity, Globe, Loader2 } from 'lucide-react';
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from '../ui/card';
import { Button } from '../ui/button';
import { Badge } from '../ui/badge';
import { ScrollArea } from '../ui/scroll-area';
import { Progress } from '../ui/progress';
import { toast } from 'sonner';
import {
    startBrowser,
    stopBrowser,
    getBrowserStatus,
    runRobotkezTest,
    getRobotkezScreenshot,
    getN8nWorkflows,
    BrowserStatus
} from '../../lib/apiService';

export function RobotkezPanel() {
    const [status, setStatus] = useState<BrowserStatus>({ active: false });
    const [loading, setLoading] = useState(false);
    const [runningTest, setRunningTest] = useState<number | null>(null);
    const [logs, setLogs] = useState<string[]>([]);
    const [screenshotUrl, setScreenshotUrl] = useState<string>('');
    const [n8nWorkflows, setN8nWorkflows] = useState<any[]>([]);
    const [n8nLoading, setN8nLoading] = useState(false);

    // Refresh status and screenshot
    const refreshData = async () => {
        try {
            // Get Browser Status
            const browserData = await getBrowserStatus();
            setStatus(browserData);

            // Get Screenshot (if active)
            if (browserData.active) {
                setScreenshotUrl(await getRobotkezScreenshot());
            } else {
                setScreenshotUrl('');
            }
        } catch (err: any) {
            console.error(err);
        }
    };

    const fetchN8nWorkflows = async () => {
        setN8nLoading(true);
        try {
            const data = await getN8nWorkflows();
            setN8nWorkflows(data.data || []);
        } catch (err: any) {
            console.error('n8n error:', err);
            // Don't toast on auto-refresh to avoid spam
            if (!n8nLoading) toast.error(`n8n hiba: ${err.message}`);
            setN8nWorkflows([]);
        } finally {
            setN8nLoading(false);
        }
    };

    // Auto-refresh hook
    useEffect(() => {
        refreshData();
        fetchN8nWorkflows();
        const interval = setInterval(() => {
            refreshData();
        }, 5000);
        return () => clearInterval(interval);
    }, []);

    const handleStart = async () => {
        setLoading(true);
        try {
            await startBrowser({
                startUrl: "https://google.com", 
                sessionName: "Dashboard Session"
            });
            toast.success("Böngésző elindítva");
            setTimeout(refreshData, 1000);
        } catch (err: any) {
            toast.error(`Hiba: ${err.message}`);
        } finally {
            setLoading(false);
        }
    };

    const handleStop = async () => {
        setLoading(true);
        try {
            await stopBrowser(status.sessionId || undefined);
            toast.info("Böngésző leállítva");
            setTimeout(refreshData, 1000);
        } catch (err: any) {
            toast.error(`Hiba: ${err.message}`);
        } finally {
            setLoading(false);
        }
    };

    const handleRunTest = async (level: 1 | 2 | 3) => {
        setRunningTest(level);
        setLogs(prev => [...prev, `\n--- Futtatás: Level ${level} teszt ---`]);
        
        try {
            // Start the test and get session ID
            const result = await runRobotkezTest(level);
            const sessionId = result.sessionId;
            
            // Connect to SSE stream
            // Note: This connects directly to Python FastAPI (port 8000)
            const evtSource = new EventSource(`http://localhost:8000/test/logs/${sessionId}`);
            
            evtSource.addEventListener('log', (e: MessageEvent) => {
                try {
                    const data = JSON.parse(e.data);
                    // Add timestamp? data.ts is available
                    setLogs(prev => [...prev, `[${data.level?.toUpperCase() || 'INFO'}] ${data.message}`]);
                } catch (err) {
                    console.error('Log parse error:', err);
                }
            });

            evtSource.addEventListener('done', (e: MessageEvent) => {
                try {
                    const data = JSON.parse(e.data);
                    setLogs(prev => [...prev, `\n--- KÉSZ (Exit: ${data.exitCode}, Idő: ${data.durationMs}ms) ---`]);
                    
                    if (data.status === 'success') {
                        toast.success(`Level ${level} teszt sikeres`);
                    } else {
                        toast.error('Teszt hibával zárult');
                    }
                } catch (err) {
                    console.error('Done parse error:', err);
                } finally {
                    evtSource.close();
                    setRunningTest(null);
                }
            });

            evtSource.onerror = (err) => {
                console.error('SSE Error:', err);
                evtSource.close();
                setRunningTest(null);
            };

        } catch (err: any) {
            toast.error(`Indítási hiba: ${err.message}`);
            setRunningTest(null);
        }
    };

    return (
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6 p-6">
            {/* Session Control Card */}
            <Card className="lg:col-span-1 shadow-lg border-primary/20 bg-card/50 backdrop-blur-sm">
                <CardHeader>
                    <div className="flex justify-between items-center">
                        <CardTitle className="flex items-center gap-2">
                            <Globe className="w-5 h-5 text-primary" />
                            Robotkéz Session
                        </CardTitle>
                        <Badge variant={status.active ? 'default' : 'secondary'} className={status.active ? 'bg-green-500/20 text-green-500 border-green-500/50' : ''}>
                            {status.active ? 'AKTÍV' : 'LEÁLLÍTVA'}
                        </Badge>
                    </div>
                </CardHeader>
                <CardContent className="space-y-4">
                    <div className="flex gap-2">
                        <Button
                            className="flex-1 gap-2"
                            onClick={handleStart}
                            disabled={loading || status.active}
                        >
                            {loading ? <Loader2 className="w-4 h-4 animate-spin" /> : <Play className="w-4 h-4" />}
                            Start
                        </Button>
                        <Button
                            variant="destructive"
                            className="flex-1 gap-2"
                            onClick={handleStop}
                            disabled={loading || !status.active}
                        >
                            <Square className="w-4 h-4" />
                            Stop
                        </Button>
                    </div>

                    <div className="pt-4 border-t border-primary/10">
                        <CardDescription className="mb-2">Teszt Futtatás (Python Subprocess)</CardDescription>
                        <div className="grid grid-cols-1 gap-2">
                            {[1, 2, 3].map(level => (
                                <Button
                                    key={level}
                                    variant="outline"
                                    className="justify-start gap-2 h-10"
                                    onClick={() => handleRunTest(level as any)}
                                    disabled={runningTest !== null}
                                >
                                    {runningTest === level ? <Loader2 className="w-4 h-4 animate-spin text-primary" /> : <Activity className="w-4 h-4 text-primary" />}
                                    Level {level} Teszt {level === 2 ? '(n8n)' : level === 3 ? '(Monitor)' : '(Navigáció)'}
                                </Button>
                            ))}
                        </div>
                    </div>
                </CardContent>
            </Card>

            {/* Live View Card */}
            <Card className="lg:col-span-2 shadow-lg border-primary/20 bg-card/50 backdrop-blur-sm overflow-hidden">
                <CardHeader className="flex flex-row items-center justify-between">
                    <CardTitle className="flex items-center gap-2 text-sm font-medium">
                        <Camera className="w-4 h-4 text-primary" />
                        Élő Nézet (5mp frissítés)
                    </CardTitle>
                    <Button variant="ghost" size="icon" onClick={refreshData}>
                        <RefreshCw className="w-4 h-4" />
                    </Button>
                </CardHeader>
                <CardContent className="p-0 border-t border-primary/10 bg-black min-h-[300px] flex items-center justify-center relative">
                    {screenshotUrl ? (
                        <img
                            src={screenshotUrl}
                            alt="Robotkéz Screenshot"
                            className="w-full h-auto object-contain cursor-zoom-in transition-transform hover:scale-105"
                            onClick={() => window.open(screenshotUrl, '_blank')}
                        />
                    ) : (
                        <div className="text-muted-foreground flex flex-col items-center gap-2">
                            <Activity className="w-8 h-8 opacity-20" />
                            <span className="text-xs uppercase tracking-widest opacity-50">Nincs aktív kép</span>
                        </div>
                    )}
                </CardContent>
            </Card>

            {/* Logs Viewer */}
            <Card className="lg:col-span-2 shadow-lg border-primary/20 bg-card/50 backdrop-blur-sm">
                <CardHeader>
                    <CardTitle className="flex items-center gap-2 text-sm font-medium">
                        <Terminal className="w-4 h-4 text-primary" />
                        Teszt Napló & Kimenet
                    </CardTitle>
                </CardHeader>
                <CardContent className="p-0">
                    <ScrollArea className="h-[200px] w-full bg-slate-950 p-4 font-mono text-xs text-green-400">
                        {logs.length === 0 ? (
                            <span className="opacity-30 italic">Üres - Várjuk a kimenetet...</span>
                        ) : (
                            logs.map((log, i) => (
                                <div key={i} className="mb-1 whitespace-pre-wrap">{log}</div>
                            ))
                        )}
                    </ScrollArea>
                </CardContent>
            </Card>

            {/* n8n Status Card */}
            <Card className="lg:col-span-1 shadow-lg border-primary/20 bg-card/50 backdrop-blur-sm">
                <CardHeader className="flex flex-row items-center justify-between">
                    <CardTitle className="flex items-center gap-2 text-sm font-medium">
                        <div className="w-2 h-2 rounded-full bg-orange-500 animate-pulse" />
                        n8n Integráció
                    </CardTitle>
                    <Button variant="ghost" size="sm" onClick={fetchN8nWorkflows} disabled={n8nLoading}>
                        {n8nLoading ? <Loader2 className="w-3 h-3 animate-spin" /> : 'FRISSÍTÉS'}
                    </Button>
                </CardHeader>
                <CardContent className="space-y-4">
                    <div className="flex justify-between items-end">
                        <div>
                            <div className="text-2xl font-bold">{n8nWorkflows.length}</div>
                            <div className="text-xs text-muted-foreground uppercase">Aktív Workflow</div>
                        </div>
                        <Progress value={Math.min(n8nWorkflows.length * 10, 100)} className="h-1 w-20" />
                    </div>

                    <div className="space-y-2">
                        {n8nWorkflows.slice(0, 3).map((wf, idx) => (
                            <div key={idx} className="flex justify-between items-center text-xs p-2 bg-secondary/30 rounded border border-primary/5">
                                <span className="font-medium truncate max-w-[120px]">{wf.name}</span>
                                <Badge variant="outline" className="text-[10px] scale-90 h-4 border-primary/20">
                                    {wf.active ? 'LIVE' : 'IDLE'}
                                </Badge>
                            </div>
                        ))}
                        {n8nWorkflows.length === 0 && (
                            <div className="text-xs text-muted-foreground p-2">Nincsenek elérhető workflow-k</div>
                        )}
                    </div>
                </CardContent>
            </Card>
        </div>
    );
}

/**
 * RobotkezV2 REST API Routes
 *
 * Replaces the old Browser-Use based robotkez with the new
 * Persistent Browser + LLM Planning approach.
 *
 * Endpoints:
 * - POST /api/v1/robotkez/chat - Natural language chat
 * - POST /api/v1/robotkez/plan - Plan preview (no execution)
 * - POST /api/v1/robotkez/exec - Direct browser action
 * - GET /api/v1/robotkez/status - Agent status
 * - GET /api/v1/robotkez/tasks - Background tasks list
 * - GET /api/v1/robotkez/tasks/:id - Task status by ID
 * - DELETE /api/v1/robotkez/tasks/:id - Cancel task
 *
 * @track robotkezv2-full-comet-20260215
 * @phase Phase 5 - REST API Endpoints
 */

import { Router, Request, Response } from 'express';
import { RobotkezV2Agent } from '../../agents/RobotkezV2Agent.js';
import { generateExecutionPlan } from '../../utils/llmPlanner.js';
import { getRobotkezBrowserEngine, getRobotkezEngineName } from '../../utils/browserEngine.js';
import { backgroundTaskManager } from '../../utils/backgroundTaskManager.js';
import { logInfo, logError } from '../../utils/logger.js';
import { getMessages, saveMessage } from '../../utils/db.js';

export function createRobotkezRoutes(): Router {
    const router = Router();
    const agent = new RobotkezV2Agent();

    /**
     * POST /api/v1/robotkez/chat
     * Natural language chat interface
     *
     * Body: { instruction: string }
     * Response: AgentResult (success, message, data)
     */
    router.post('/chat', async (req: Request, res: Response) => {
        try {
            const { instruction } = req.body;

            if (!instruction || typeof instruction !== 'string') {
                return res.status(400).json({
                    success: false,
                    error: 'Missing or invalid "instruction" field'
                });
            }

            logInfo('RobotkezAPI', `Chat request: "${instruction}"`);

            const CHAT_ID = 'robotkez-chat';
            
            // Save user message
            await saveMessage(CHAT_ID, 'user', instruction);

            // Get history (last 10 messages)
            const allMessages = await getMessages(CHAT_ID);
            const history = allMessages.slice(-10).map(m => ({
                role: m.role,
                content: m.content
            }));

            const result = await agent.execute(instruction, { 
                swarm: { 
                    sessionId: CHAT_ID,
                    history,
                    artifacts: {}
                } 
            });

            // Save assistant response
            if (result.status === 'success' || result.status === 'handoff') {
                await saveMessage(CHAT_ID, 'assistant', result.message || 'Kész');
            }

            res.json(result);

        } catch (error: unknown) {
            const msg = error instanceof Error ? error.message : String(error);
            logError('RobotkezAPI', `Chat error: ${msg}`);
            res.status(500).json({
                success: false,
                error: msg
            });
        }
    });

    /**
     * POST /api/v1/robotkez/plan
     * Generate execution plan without executing (preview mode)
     *
     * Body: { instruction: string }
     * Response: { plan: ExecutionPlan }
     */
    router.post('/plan', async (req: Request, res: Response) => {
        try {
            const { instruction } = req.body;

            if (!instruction || typeof instruction !== 'string') {
                return res.status(400).json({
                    success: false,
                    error: 'Missing or invalid "instruction" field'
                });
            }

            logInfo('RobotkezAPI', `Plan request: "${instruction}"`);

            const plan = await generateExecutionPlan(instruction);

            res.json({
                success: true,
                plan,
                message: `Plan generálva: ${plan.plan.length} lépés`
            });

        } catch (error: unknown) {
            const msg = error instanceof Error ? error.message : String(error);
            logError('RobotkezAPI', `Plan error: ${msg}`);
            res.status(500).json({
                success: false,
                error: msg
            });
        }
    });

    /**
     * POST /api/v1/robotkez/exec
     * Execute direct browser action (low-level)
     *
     * Body: { action: string, ...params }
     * Examples:
     * - { action: 'navigate', url: 'https://google.com' }
     * - { action: 'click', selector: '.button' }
     * - { action: 'type', selector: 'input', text: 'hello' }
     */
    router.post('/exec', async (req: Request, res: Response) => {
        try {
            const { action, ...params } = req.body;

            if (!action) {
                return res.status(400).json({
                    success: false,
                    error: 'Missing "action" field'
                });
            }

            logInfo('RobotkezAPI', `Exec request: ${action}`);

            const browserEngine = getRobotkezBrowserEngine();

            const result = await browserEngine.sendCommand({
                action,
                ...params
            });

            res.json({
                success: true,
                result,
                message: `Action executed: ${action}`
            });

        } catch (error: unknown) {
            const msg = error instanceof Error ? error.message : String(error);
            logError('RobotkezAPI', `Exec error: ${msg}`);
            res.status(500).json({
                success: false,
                error: msg
            });
        }
    });

    /**
     * GET /api/v1/robotkez/status
     * Get agent and browser status
     *
     * Response: { agent, browser, tasks }
     */
    router.get('/status', async (req: Request, res: Response) => {
        try {
            const tasks = backgroundTaskManager.getAllTasks();
            const runningTasks = tasks.filter(t => t.status === 'running');

            res.json({
                success: true,
                agent: {
                    name: agent.name,
                    role: agent.role,
                    capabilities: agent.capabilities
                },
                browser: {
                    active: true, // TODO: Check actual browser status
                    type: 'persistent',
                    engine: getRobotkezEngineName() === 'cloudflare' ? 'Cloudflare Browser Rendering' : 'Playwright + Python'
                },
                browserStatus: runningTasks.length > 0 ? 'running' : 'idle', // For test compatibility
                tasks: {
                    total: tasks.length,
                    running: runningTasks.length,
                    completed: tasks.filter(t => t.status === 'completed').length,
                    error: tasks.filter(t => t.status === 'error').length
                }
            });

        } catch (error: unknown) {
            const msg = error instanceof Error ? error.message : String(error);
            logError('RobotkezAPI', `Status error: ${msg}`);
            res.status(500).json({
                success: false,
                error: msg
            });
        }
    });

    /**
     * GET /api/v1/robotkez/tasks
     * List all background tasks
     *
     * Query params:
     * - status?: 'running' | 'completed' | 'error' | 'cancelled'
     * - limit?: number (default: 50)
     *
     * Response: { tasks: BackgroundTask[] }
     */
    router.get('/tasks', async (req: Request, res: Response) => {
        try {
            const { status, limit } = req.query;

            let tasks = backgroundTaskManager.getAllTasks();

            // Filter by status if provided
            if (status && typeof status === 'string') {
                const statusStr = Array.isArray(status) ? status[0] : status;
                tasks = tasks.filter(t => t.status === statusStr);
            }

            // Apply limit
            const limitStr = Array.isArray(limit) ? limit[0] : limit;
            const limitNum = limitStr ? parseInt(limitStr as string, 10) : 50;
            tasks = tasks.slice(0, limitNum);

            res.json({
                success: true,
                tasks,
                count: tasks.length
            });

        } catch (error: unknown) {
            const msg = error instanceof Error ? error.message : String(error);
            logError('RobotkezAPI', `Tasks list error: ${msg}`);
            res.status(500).json({
                success: false,
                error: msg
            });
        }
    });

    /**
     * GET /api/v1/robotkez/tasks/:id
     * Get single task status by ID
     *
     * Response: { task: BackgroundTask }
     */
    router.get('/tasks/:id', async (req: Request, res: Response) => {
        try {
            const id = req.params.id as string;

            const task = backgroundTaskManager.getTaskStatus(id);

            if (!task) {
                return res.status(404).json({
                    success: false,
                    error: `Task not found: ${id}`
                });
            }

            res.json({
                success: true,
                task
            });

        } catch (error: unknown) {
            const msg = error instanceof Error ? error.message : String(error);
            logError('RobotkezAPI', `Task status error: ${msg}`);
            res.status(500).json({
                success: false,
                error: msg
            });
        }
    });

    /**
     * DELETE /api/v1/robotkez/tasks/:id
     * Cancel running task
     *
     * Response: { cancelled: boolean }
     */
    router.delete('/tasks/:id', async (req: Request, res: Response) => {
        try {
            const id = req.params.id as string;

            const cancelled = backgroundTaskManager.cancelTask(id);

            if (!cancelled) {
                return res.status(400).json({
                    success: false,
                    error: `Task cannot be cancelled (not running or not found): ${id}`
                });
            }

            res.json({
                success: true,
                cancelled: true,
                message: `Task ${id} cancelled`
            });

        } catch (error: unknown) {
            const msg = error instanceof Error ? error.message : String(error);
            logError('RobotkezAPI', `Task cancel error: ${msg}`);
            res.status(500).json({
                success: false,
                error: msg
            });
        }
    });

    /**
     * GET /api/v1/robotkez/screenshot
     * Get latest browser screenshot (PNG image)
     *
     * Response: PNG image (Content-Type: image/png)
     */
    router.get('/screenshot', async (req: Request, res: Response) => {
        try {
            const browserEngine = getRobotkezBrowserEngine();
            const screenshot = browserEngine.getLastScreenshot();

            if (!screenshot) {
                return res.status(404).json({
                    success: false,
                    error: 'No screenshot available'
                });
            }

            res.setHeader('Content-Type', 'image/png');
            res.setHeader('Cache-Control', 'no-cache, no-store, must-revalidate');
            res.send(Buffer.from(screenshot));

        } catch (error: unknown) {
            const msg = error instanceof Error ? error.message : String(error);
            logError('RobotkezAPI', `Screenshot error: ${msg}`);
            res.status(500).json({
                success: false,
                error: msg
            });
        }
    });

    return router;
}

