    const [alerts, setAlerts] = useState<BuyAlert[]>([]);
    const [isHunting, setIsHunting] = useState(false);
    const { socket } = useSocket();

    // Socket.IO eseménykezelés valós idejű riasztásokhoz
    useEffect(() => {
        if (!socket) return;

