// index.js

export default {

&nbsp; async fetch(request, env) {

&nbsp; const url = new URL(request.url);

&nbsp; &nbsp; // Route: /chat - Chat endpoint magyar nyelvű utasításokhoz

&nbsp; if (url.pathname === '/chat') {

&nbsp; return handleChat(request, env);

&nbsp; }

&nbsp; &nbsp; // Route: /screenshot - Screenshot endpoint élő képernyőhöz

&nbsp; if (url.pathname === '/screenshot') {

&nbsp; return handleScreenshot(request, env);

&nbsp; }

&nbsp; &nbsp; // Route: /health - Health check

&nbsp; if (url.pathname === '/health') {

&nbsp; return new Response('OK', { status: 200 });

&nbsp; }

&nbsp; &nbsp; return new Response('Not found', { status: 404 });

&nbsp; }

};

async function handleChat(request, env) {

&nbsp; const data = await request.json();

&nbsp; const { message, sessionId } = data;

&nbsp; &nbsp; // Browser Rendering inicializálása

&nbsp; const browser = await env.BROWSER.render();

&nbsp; const page = await browser.newPage();

&nbsp; &nbsp; // AI model használata (Workers AI vagy OpenAI)

&nbsp; const aiResponse = await processMessage(message, env, page);

&nbsp; &nbsp; // Screenshot készítése

&nbsp; const screenshot = await page.screenshot({ fullPage: false });

&nbsp; &nbsp; // Szesszió bezárása

&nbsp; await browser.close();

&nbsp; &nbsp; return new Response(JSON.stringify({

&nbsp; response: aiResponse,

&nbsp; screenshot: screenshot.toString('base64'),

&nbsp; sessionId

&nbsp; }), {

&nbsp; headers: { 'Content-Type': 'application/json' }

&nbsp; });

}

async function handleScreenshot(request, env) {

&nbsp; const browser = await env.BROWSER.render();

&nbsp; const page = await browser.newPage();

&nbsp; &nbsp; // Screenshot készítése

&nbsp; const screenshot = await page.screenshot({ fullPage: false });

&nbsp; await browser.close();

&nbsp; &nbsp; return new Response(screenshot, {

&nbsp; headers: { 'Content-Type': 'image/png' }

&nbsp; });

}

async function processMessage(message, env, page) {

&nbsp; // AI model használata magyar nyelvű utasításokhoz

