from fastapi import FastAPI, WebSocket, WebSocketDisconnect

from pydantic import BaseModel

import base64

import asyncio

from typing import Optional

from playwright.async\_api import async\_playwright

app = FastAPI(title="Brunella Browser Automation")

class ChatRequest(BaseModel):

&nbsp; message: str

&nbsp; session\_id: Optional\[str] = None

class ChatResponse(BaseModel):

&nbsp; response: str

&nbsp; screenshot: Optional\[str] = None

&nbsp; session\_id: str

 @app.post("/browser/chat", response\_model=ChatResponse)

async def browser\_chat(request: ChatRequest):

&nbsp; """Magyar nyelvű chat endpoint böngésző automatizációhoz"""

&nbsp; &nbsp; async with async\_playwright() as p:

&nbsp; browser = await p.chromium.launch(headless=False)

&nbsp; page = await browser.new\_page()

&nbsp; &nbsp; # AI model használata (OpenAI vagy Workers AI)

&nbsp; ai\_response = await process\_message(request.message, page)

&nbsp; &nbsp; # Screenshot készítése

&nbsp; screenshot\_bytes = await page.screenshot(full\_page=False)

&nbsp; screenshot\_base64 = base64.b64encode(screenshot\_bytes).decode('utf-8')

&nbsp; &nbsp; await browser.close()

&nbsp; &nbsp; return ChatResponse(

&nbsp; response=ai\_response,

&nbsp; screenshot=screenshot\_base64,

&nbsp; session\_id=request.session\_id or f"session\_{int(asyncio.get\_event\_loop().time())}"

&nbsp; )

 @app.get("/browser/screenshot")

async def browser\_screenshot():

&nbsp; """Élő screenshot endpoint"""

&nbsp; &nbsp; async with async\_playwright() as p:

&nbsp; browser = await p.chromium.launch(headless=False)

&nbsp; page = await browser.new\_page()

&nbsp; &nbsp; screenshot\_bytes = await page.screenshot(full\_page=False)

&nbsp; await browser.close()

&nbsp; &nbsp; return screenshot\_bytes

async def process\_message(message: str, page) -> str:

&nbsp; """AI model használata magyar nyelvű utasításokhoz"""

&nbsp; # Itt lehet OpenAI, Gemini vagy Workers AI használata

&nbsp; # Példa: Stagehand observe + act

&nbsp; &nbsp; actions = await page.observe(message)

&nbsp; &nbsp; for action in actions:

&nbsp; await page.act(action)

&nbsp; &nbsp; return f"Készítettem: {message}"

