// src/components/ChatInterface.tsx

import React, { useState, useEffect, useRef } from 'react';

import axios from 'axios';

interface Message {

&nbsp; id: string;

&nbsp; text: string;

&nbsp; sender: 'user' | 'agent';

&nbsp; timestamp: Date;

&nbsp; screenshot?: string;

}

const ChatInterface: React.FC = () => {

&nbsp; const \[messages, setMessages] = useState<Message\[]>(\[]);

&nbsp; const \[input, setInput] = useState('');

&nbsp; const \[screenshot, setScreenshot] = useState<string>('');

&nbsp; const \[isTyping, setIsTyping] = useState(false);

&nbsp; const messagesEndRef = useRef<HTMLDivElement>(null);

&nbsp; &nbsp; const chatEndpoint = process.env.REACT\_APP\_BROWSER\_CHAT\_ENDPOINT || 'http://localhost:3000/browser/chat';

&nbsp; const screenshotEndpoint = process.env.REACT\_APP\_BROWSER\_SCREENSHOT\_ENDPOINT || 'http://localhost:3000/browser/screenshot';

&nbsp; &nbsp; useEffect(() => {

&nbsp; scrollToBottom();

&nbsp; }, \[messages, screenshot]);

&nbsp; &nbsp; // Automatikus screenshot frissítés 2mp-enként

&nbsp; useEffect(() => {

&nbsp; const interval = setInterval(async () => {

&nbsp; if (messages.length > 0) {

&nbsp; try {

&nbsp; const response = await axios.get(screenshotEndpoint, {

&nbsp; responseType: 'arraybuffer'

&nbsp; });

&nbsp; const base64 = Buffer.from(response.data, 'binary').toString('base64');

&nbsp; setScreenshot(base64);

&nbsp; } catch (error) {

&nbsp; console.error('Screenshot error:', error);

&nbsp; }

&nbsp; }

&nbsp; }, 2000);

&nbsp; &nbsp; return () => clearInterval(interval);

&nbsp; }, \[messages.length]);

&nbsp; &nbsp; const scrollToBottom = () => {

&nbsp; messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });

&nbsp; };

&nbsp; &nbsp; const handleSend = async () => {

&nbsp; if (!input.trim()) return;

&nbsp; &nbsp; const userMessage: Message = {

&nbsp; id: Date.now().toString(),

&nbsp; text: input,

&nbsp; sender: 'user',

&nbsp; timestamp: new Date()

&nbsp; };

&nbsp; &nbsp; setMessages(\[...messages, userMessage]);

&nbsp; setInput('');

&nbsp; setIsTyping(true);

&nbsp; &nbsp; try {

&nbsp; const response = await axios.post(chatEndpoint, {

&nbsp; message: input,

&nbsp; session\_id: messages.length > 0 ? messages\[messages.length - 1].id : undefined

&nbsp; });

&nbsp; &nbsp; const agentMessage: Message = {

&nbsp; id: response.data.session\_id,

&nbsp; text: response.data.response,

&nbsp; sender: 'agent',

&nbsp; timestamp: new Date(),

